// Generates src/lib/api/endpoints.gen.ts from the @app/contracts endpoint table.
// The generated file holds only method, path, status and flags, so the client's first
// load does not ship zod and the schemas. Types still come from @app/contracts.
//
//   pnpm --filter @app/web gen:endpoints
//
// A test (src/lib/api/endpoints.test.ts) fails while the generated file is stale.
import { writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { endpointList } from '@app/contracts';

export const GENERATED_PATH = join(import.meta.dirname, '../src/lib/api/endpoints.gen.ts');

export function renderEndpointsFile(): string {
  const lines = endpointList.map((e) => {
    const meta = {
      method: e.method,
      path: e.path,
      status: e.status,
      auth: e.auth,
      stream: e.stream !== undefined,
    };
    return `  '${e.name}': ${JSON.stringify(meta)},`;
  });
  return [
    '// Generated by apps/web/scripts/endpoints-gen.ts from the @app/contracts endpoint table.',
    '// Do not edit. Run `pnpm --filter @app/web gen:endpoints` after a contract change.',
    "import type { EndpointName } from '@app/contracts';",
    '',
    'export interface EndpointMeta {',
    "  readonly method: 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';",
    '  /** Below the API base, with `:param` placeholders. */',
    '  readonly path: string;',
    '  readonly status: 200 | 201 | 202 | 204;',
    '  readonly auth: boolean;',
    '  /** True only for the tutor message stream. */',
    '  readonly stream: boolean;',
    '}',
    '',
    'export const ENDPOINT_META = {',
    ...lines,
    '} as const satisfies Record<EndpointName, EndpointMeta>;',
    '',
  ].join('\n');
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  writeFileSync(GENERATED_PATH, renderEndpointsFile());
  console.log(`wrote ${GENERATED_PATH}`);
}
